static void
draw_cursor(struct vt_window *vw, int col, int row)
{
	unsigned char *p;
	int x, y;

	p = vw->vw_buffer + (row * vw->vw_stride);
	p += col;

	if (*p == 0) {
		/* Clear the cursor area. */
		for (y = 0; y < 15; y++)
			for (x = 0; x < 14; x++)
				p[y * vw->vw_stride + x] = ' ';
	}
}

static inline unsigned short
count (void *p)
{
  unsigned char *pc = p;
  unsigned short old_count = pc[-1];
  unsigned short new_count;
  pc[-1] = 0;
  new_count = ((unsigned) pc[-2] << 8) | pc[-1];
  pc[-1] = old_count;
  return new_count;
}

static void
draw_hline(u_char * p, int linesize, int x, int y, int w, int h, int color)
{
	u_char *dest = p + y * linesize + x;
	unsigned char *s = (unsigned char *)dest;
	unsigned char *ss;
	unsigned char c = color ? 0xff : 0x00;

	while (h--)
	{
		ss = &c;
		dest = s + 32;
		while (w--)
		{
			*s++ = *ss;
			*s++ = *ss;
			*s++ = *ss;
			s++;
		}
		dest += linesize - 32;
		s = (unsigned char *)dest;
	}
}

